package com.bank.payment;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.logging.Logger;

public class AuditBuffer {
    private static final Logger log = Logger.getLogger(AuditBuffer.class.getName());
    private final List<String> entries = new CopyOnWriteArrayList<>();

    public void record(String entry) { entries.add(entry); }

    // Called by the shutdown hook — must be fast.
    public void flush() {
        log.info(() -> "Flushing " + entries.size() + " audit entries to durable store");
        entries.clear();
    }
    public int size() { return entries.size(); }
}
