package com.bank.payment;

import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.logging.Logger;

public class PaymentProcessor {
    private static final Logger log = Logger.getLogger(PaymentProcessor.class.getName());
    private final ExecutorService pool = Executors.newFixedThreadPool(4);
    private final AuditBuffer audit = new AuditBuffer();
    private final AtomicBoolean running = new AtomicBoolean(true);

    public PaymentProcessor() {
        // Register the graceful shutdown hook once at startup.
        Runtime.getRuntime().addShutdownHook(new Thread(this::gracefulShutdown, "shutdown-hook"));
    }

    public void submitPayment(String fromId, String toId, BigDecimal amount) {
        if (!running.get()) {
            log.warning(() -> "Rejected payment " + fromId + "→" + toId + " (shutting down)");
            return;
        }
        pool.submit(() -> {
            // persist transactionally AS WE GO (not deferred to shutdown)
            try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            audit.record("PAY " + fromId + "→" + toId + " " + amount);
            log.info(() -> "Processed payment " + fromId + "→" + toId + " " + amount);
        });
    }

    // Runs on SIGTERM / System.exit / Ctrl-C — NOT on kill -9.
    void gracefulShutdown() {
        log.info("Shutdown hook started — draining payments");
        running.set(false);            // stop accepting new payments
        pool.shutdown();               // finish in-flight tasks
        try {
            // bounded wait so we stay within the orchestrator grace period
            if (!pool.awaitTermination(10, TimeUnit.SECONDS)) {
                log.warning("Timed out — interrupting stragglers");
                pool.shutdownNow();
            }
        } catch (InterruptedException e) {
            pool.shutdownNow();
            Thread.currentThread().interrupt();
        }
        audit.flush();                 // best-effort flush
        log.info("Graceful shutdown complete");
    }

    public AuditBuffer getAudit() { return audit; }
}
