package com.bank.payment;

import java.math.BigDecimal;

public class ShutdownHookDemo {
    public static void main(String[] args) {
        PaymentProcessor processor = new PaymentProcessor();
        processor.submitPayment("SAV2001", "CUR3001", new BigDecimal("50000"));
        processor.submitPayment("CUR3001", "SAV2001", new BigDecimal("12000"));
        processor.submitPayment("SAV2001", "CUR3001", new BigDecimal("8000"));

        // Normal exit triggers the shutdown hook (same path as SIGTERM).
        System.out.println("Main done — JVM exiting, hook will drain payments");
    }
}
