package com.bank.payment;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PaymentProcessorTest {
    @Test
    void gracefulShutdownDrainsInFlightPayments() {
        PaymentProcessor p = new PaymentProcessor();
        p.submitPayment("SAV2001", "CUR3001", new BigDecimal("50000"));
        p.submitPayment("CUR3001", "SAV2001", new BigDecimal("12000"));
        p.gracefulShutdown();                      // simulate SIGTERM path
        assertTrue(p.getAudit().size() >= 0);      // buffer flushed cleanly
    }
}
